// =============================================================================
// DOM stability steps
// =============================================================================

// Store rendered item references before a mutating action so we can
// verify that the DOM nodes are preserved (not rebuilt).
Then('the {string} item element is the same DOM node as before the toggle', function (title) {
  // The step stores a snapshot of item elements before toggle and compares
  if (!this._savedNodes) {
    throw new Error('No saved DOM node snapshot found. The When step must be preceded by a snapshot step.');
  }
  const li = findTodoItem(this, title);
  if (!li) {
    throw new Error('Could not find todo item "' + title + '"');
  }
  const saved = this._savedNodes.get(title);
  if (!saved) {
    throw new Error('No saved node for "' + title + '" — verify the snapshot captured it');
  }
  if (li !== saved) {
    throw new Error(
      'Expected "' + title + '" item element to be the same DOM node, but it was replaced. ' +
      'Old node: ' + saved.outerHTML + ', new node: ' + li.outerHTML
    );
  }
});

Then('each item element is the same DOM node as before the toggle-all', function () {
  if (!this._savedNodes) {
    throw new Error('No saved DOM node snapshot found');
  }
  const currentItems = getTodoList(this);
  if (currentItems.length === 0) {
    throw new Error('No items in the todo list');
  }
  const failures = [];
  currentItems.forEach(function (li) {
    const label = li.querySelector('.view label');
    if (!label) return;
    const title = label.textContent;
    const saved = this._savedNodes.get(title);
    if (!saved) {
      failures.push('No saved node for "' + title + '"');
    } else if (li !== saved) {
      failures.push('"' + title + '" element was replaced');
    }
  }, this);
  if (failures.length > 0) {
    throw new Error('DOM node stability failures: ' + failures.join('; '));
  }
});

