// Mutate existing DOM nodes in-place rather than rebuilding via innerHTML.
// This preserves element references across state changes.
var existingItems = Array.prototype.slice.call(list.querySelectorAll('li'));
var existingById = {};
existingItems.forEach(function (li) {
  var id = Number(li.getAttribute('data-id'));
  existingById[id] = li;
});

filtered.forEach(function (todo, idx) {
  var li = existingById[todo.id];
  if (li) {
    // Update existing node in-place
    var completedClass = todo.completed ? 'completed' : '';
    var editingClass = self.editingId === todo.id ? 'editing' : '';
    li.className = (completedClass + ' ' + editingClass).trim();
    var checkbox = li.querySelector('.toggle');
    if (checkbox) checkbox.checked = todo.completed;
    var label = li.querySelector('label');
    if (label) label.textContent = todo.title;
    var editInput = li.querySelector('.edit');
    if (editInput) editInput.value = todo.title.replace(/"/g, '&quot;');
    // Move li to correct position if needed
    var currentIdx = Array.prototype.indexOf.call(list.children, li);
    if (currentIdx !== idx) {
      var ref = list.children[idx];
      if (ref && ref !== li) {
        list.insertBefore(li, ref);
      } else if (!ref) {
        list.appendChild(li);
      }
    }
    delete existingById[todo.id];
  } else {
    // Create new element for items not yet in the DOM
    var completedClass = todo.completed ? 'completed' : '';
    var editingClass = self.editingId === todo.id ? 'editing' : '';
    li = document.createElement('li');
    li.className = (completedClass + ' ' + editingClass).trim();
    li.setAttribute('data-id', todo.id);
    li.innerHTML =
      '<div class="view">' +
      '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
      '<label>' + todo.title + '</label>' +
      '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + todo.title.replace(/"/g, '&quot;') + '">';
    if (idx < list.children.length) {
      list.insertBefore(li, list.children[idx]);
    } else {
      list.appendChild(li);
    }
  }
});

// Remove stale elements (completed items after clear-completed, etc.)
Object.keys(existingById).forEach(function (id) {
  var li = existingById[id];
  if (li.parentNode) li.parentNode.removeChild(li);
});

